const builtTemplates=[{name:'TikTok 50 / 50',ratio:'9:16',split:50,layout:'split'},{name:'TikTok webcam above gameplay',ratio:'9:16',split:30,layout:'split'},{name:'TikTok picture in picture',ratio:'9:16',split:25,layout:'pip'},{name:'YouTube facecam',ratio:'16:9',split:25,layout:'pip'},{name:'Instagram square',ratio:'1:1',split:50,layout:'single'}];
async function applyTemplate(template){if(template.project){const copy=M.clone(template.project),map=new Map();for(const a of template.assets||[]){const result=await call('importPaths',[a.path]);if(result.errors.length)throw new Error(result.errors.join(' · '));map.set(a.id,result.media[0].id);assets.set(result.media[0].id,result.media[0]);}for(const item of copy.items)if(item.mediaId)item.mediaId=map.get(item.mediaId);copy.id=M.id();mutate(()=>{history.project=copy;});render();return;}
  const videos=project().items.filter(i=>selected.has(i.id)&&['video','image'].includes(i.type));if(!videos.length)throw new Error('Select one or two video/image items to place in the template.');mutate(p=>{p.settings.ratio=template.ratio;const base=Math.min(...videos.map(i=>i.start));videos.slice(0,2).forEach((i,index)=>{i.start=base;if(template.layout==='split'){let track=p.tracks.find(t=>t.name==='Template '+(index+1));if(!track){track={id:M.id(),kind:'video',name:'Template '+(index+1),volume:1,hidden:false,muted:false};p.tracks.push(track);}i.trackId=track.id;const proportion=index===0?template.split:100-template.split;i.transform={...i.transform,fit:'cover',width:100,height:proportion,x:0,y:index===0?-(100-template.split)/2:template.split/2};}else if(template.layout==='pip'){i.transform={...i.transform,fit:'cover',width:index===0?100:template.split,height:index===0?100:template.split,x:index===0?0:32,y:index===0?0:-32};}else i.transform={...i.transform,width:100,height:100,x:0,y:0};});});}
