async function saveAsset(asset){settings=await call('assetRole',{id:asset.id,role:'library'});notice('Added to your local asset library. Original media stays in its folder.');}
async function toggleFavourite(key){if(key.startsWith('asset:')){const id=key.slice(6),asset=assets.get(id)||[...assets.values()].find(a=>a.libraryId===id);if(asset){const result=await call('favouriteAsset',asset.id);settings=result.settings;asset.libraryId=result.libraryId;renderPanel();return;}}const set=new Set(settings.favourites);set.has(key)?set.delete(key):set.add(key);settings={...settings,favourites:[...set]};await call('settings',settings);renderPanel();}
function libraryPanel(parent){row(parent).append(button('＋ Save selected asset',()=>{const i=primary();if(!i?.mediaId)throw new Error('Select a media item first.');return saveAsset(assets.get(i.mediaId));}),button('＋ Quick access folder',addFolder));for(const a of settings.library){const card=el('div',undefined,'list-item');card.append(el('strong',iconFor(a)+' '+a.name),el('small',a.kind));row(card).append(button('＋ Import',async()=>{const result=await call('importPaths',[a.path]);if(result.errors.length)throw new Error(result.errors.join(' · '));addMedia(result.media[0],time);}),button('⌫ Forget',async()=>{settings.library=settings.library.filter(v=>v.path!==a.path);await call('settings',settings);renderPanel();}));parent.append(card);}heading(parent,'▱ Quick access directories');for(const folder of settings.folders){parent.append(button('▱ '+folder,async()=>{const files=await call('listFolder',folder);await modal('▱ '+folder,body=>{for(const file of files)body.append(button('＋ '+file.name,async()=>{await importMedia([file.path]);closeModal();},'wide'));});}));}}
async function addFolder(){const folder=await call('choose','folder');if(folder&&!settings.folders.includes(folder)){settings.folders.push(folder);await call('settings',settings);renderPanel();}}
function favouritesPanel(parent){const groups=new Map();for(const key of settings.favourites){const category=key.split(':')[0];if(!groups.has(category))groups.set(category,[]);groups.get(category).push(key.slice(category.length+1));}if(!groups.size)parent.append(el('p','Use ☆ beside media, templates, fonts, voices, or filters to keep them here.','hint'));for(const [kind,values]of groups){heading(parent,'★ '+kind);for(const value of values){const r=row(parent),name=kind==='asset'?assets.get(value)?.name||settings.library.find(a=>a.id===value)?.name||'Source no longer available':value;r.append(button('★ '+name,()=>{if(kind==='asset'){const a=assets.get(value)||[...assets.values()].find(a=>a.libraryId===value);if(a)addMedia(a,time);else{const entry=settings.library.find(a=>a.id===value);if(!entry)throw new Error('Source is no longer available.');return importMedia([entry.path]);}}if(kind==='font')changeItem(i=>{if(i.style)i.style.font=value;});if(kind==='voice'){settings.speechVoice=value;return call('settings',settings);}if(kind==='template'){const t=[...builtTemplates,...settings.templates].find(t=>t.name===value);if(t)return applyTemplate(t);}if(kind==='filter')changeItem(i=>{if(i.adjust)i.adjust.filter=value;});if(kind==='transition')changeItem(i=>{if(i.transition)i.transition.kind=value;});}),button('⌫',()=>toggleFavourite(kind+':'+value)));}}const i=primary();if(i?.adjust)row(parent).append(button('★ Current filter',()=>toggleFavourite('filter:'+i.adjust.filter)),button('★ Current transition',()=>toggleFavourite('transition:'+i.transition.kind)));}
