function keyMatches(event,binding){const bits=binding.split('+'),key=bits.pop(),mod=bits.includes('Mod'),isMac=/Mac/.test(navigator.platform);if(mod&&!(isMac?event.metaKey:event.ctrlKey))return false;if(!mod&&(event.ctrlKey||event.metaKey)&&!bits.includes('Ctrl')&&!bits.includes('Meta'))return false;if(!!event.shiftKey!==bits.includes('Shift')||!!event.altKey!==bits.includes('Alt'))return false;if(bits.includes('Ctrl')&&!event.ctrlKey||bits.includes('Meta')&&!event.metaKey)return false;return event.code===key||event.code==='Key'+key.toUpperCase()||event.key.toLowerCase()===key.toLowerCase();}
document.addEventListener('keydown',safe(e=>{if(e.target.matches('input,select,textarea')||$('modal').open)return;for(const [action,binding]of [...Object.entries(settings.shortcuts),...settings.customShortcuts.map(k=>[k.action,k.binding])])if(keyMatches(e,binding)){e.preventDefault();return actions[action]?.();}}));
function divider(id,property,min,max,horizontal){$(id).onpointerdown=e=>{const rect=$('studio').getBoundingClientRect(),start=e.clientX,value=settings.inspectorWidth;$(id).setPointerCapture?.(e.pointerId);const move=ev=>{const number=horizontal?Math.max(min,Math.min(max,ev.clientY-rect.top)):Math.max(min,Math.min(max,value+(settings.toolbarEdge==='right'?-1:1)*(ev.clientX-start)));document.documentElement.style.setProperty(property,number+'px');if(horizontal)settings.previewHeight=number;else settings.inspectorWidth=number;};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);void call('settings',settings);};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);};$(id).onkeydown=e=>{const change=e.key==='ArrowLeft'||e.key==='ArrowUp'?-10:e.key==='ArrowRight'||e.key==='ArrowDown'?10:0;if(change){e.preventDefault();const key=horizontal?'previewHeight':'inspectorWidth';settings[key]=Math.max(min,Math.min(max,settings[key]+change));applySettings();void call('settings',settings);}};}
