$('tracks').addEventListener('pointerdown',e=>{if(e.target.closest('.asset,.track-head')||e.button!==0)return;const start={x:e.clientX,y:e.clientY},rect=$('marquee');if(!e.ctrlKey&&!e.metaKey)selected.clear();const original=new Set(selected);rect.hidden=false;const move=ev=>{const x=Math.min(start.x,ev.clientX),y=Math.min(start.y,ev.clientY),w=Math.abs(ev.clientX-start.x),h=Math.abs(ev.clientY-start.y);Object.assign(rect.style,{left:x+'px',top:y+'px',width:w+'px',height:h+'px'});selected=new Set(original);document.querySelectorAll('.asset').forEach(n=>{const r=n.getBoundingClientRect();if(r.right>=x&&r.left<=x+w&&r.bottom>=y&&r.top<=y+h)selected.add(n.dataset.item);n.classList.toggle('selected',selected.has(n.dataset.item));});};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);rect.hidden=true;render();};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);});
