function analytics(){const histogram=$('histogram');if(!settings.analytics||!compositor.context)return;try{const canvas=document.createElement('canvas');canvas.width=96;canvas.height=54;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage($('preview-canvas'),0,0,96,54);const data=ctx.getImageData(0,0,96,54).data,bins=[new Array(64).fill(0),new Array(64).fill(0),new Array(64).fill(0)];for(let i=0;i<data.length;i+=4)for(let c=0;c<3;c++)bins[c][Math.floor(data[i+c]/4)]++;histogram.width=600;histogram.height=70;const out=histogram.getContext('2d'),max=Math.max(...bins.flat());out.clearRect(0,0,600,70);for(let c=0;c<3;c++){out.strokeStyle=['#ed617d','#7bdb9c','#79a9ef'][c];out.beginPath();bins[c].forEach((v,n)=>{if(n)out.lineTo(n/63*600,70-v/max*68);else out.moveTo(0,70-v/max*68);});out.stroke();}}catch{}}
